-- Prometheus Foundation grantee edges. org 8 = Prometheus Foundation.
-- Source: every https://prometheusfdn.org/grantees/<slug>/ page, enumerated by
-- grantees-sitemap.xml and each individually fetched with a 200 (see
-- prometheus_grantees_runlog.csv). Name spellings are kept exactly as published,
-- so 'Ayn Rand Centre UK' and 'Ayn Rand Center Japan' differ deliberately.

UPDATE relationships SET start_date=COALESCE(start_date,'2011'), evidence=COALESCE(NULLIF(evidence,''),'IRS Form 990, Prometheus Foundation, EIN 27-1456655 (Crystal Bay, NV; 501(c)(3), ruling 2010-09). Filings with data FY2011-2015 and FY2019-2023; FY2023 total revenue $3,800,194, total assets $68,229,080; FY2019 total revenue $18,937,877. Per-grantee amounts appear only in Schedule I of the filing PDFs and are not attached here. Objective Standard Institute is EIN 84-3575279 (Glen Allen, VA).'), source_url=COALESCE(NULLIF(source_url,''),'https://projects.propublica.org/nonprofits/organizations/271456655') WHERE org_id=8 AND related_org_id=3 AND relationship_type='funds';
UPDATE relationships SET confidence='retired', evidence='Not present on https://objectivestandard.org/team/ as fetched 2026-09-20 (100,078 bytes, zero occurrences of Upmann). No departure date published, so end_date stays NULL rather than being invented.', source_url='https://objectivestandard.org/team/' WHERE person_id=44 AND org_id=3;
